import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";
import "./signal-strength.css";

export type SignalStrengthProps = Omit<ComponentProps<"span">, "children"> & {
  /** Bars lit, from 0 to 4. */
  level: number;
  /** Searching sweeps the bars; offline greys them out with a slash. */
  status?: "connected" | "searching" | "offline";
  /** What the signal is of, e.g. "Network". Pass "" when the row says it already. */
  label?: string;
  size?: "sm" | "md";
};

const quality = ["No signal", "Poor", "Fair", "Good", "Excellent"];

/**
 * Four bars for the quality of a connection: a call, a sync, a device's network. The bars rise and fall one after
 * another as the level changes and take a colour for how good it is (red poor, amber fair, green good); while
 * searching a light sweeps across them, and offline they grey out under a slash. Under reduced motion the bars
 * change without rising and the sweep is replaced by a dim pulse.
 */
export function SignalStrength({ level, status = "connected", label = "Signal", size = "md", className, style, ...props }: SignalStrengthProps) {
  const lit = status === "connected" ? Math.max(0, Math.min(4, Math.round(level))) : 0;
  const name = status === "connected" ? `${quality[lit]}, ${lit} of 4 bars` : status === "searching" ? "Searching" : "Offline";
  return (
    <span
      role={label ? "img" : undefined}
      aria-label={label ? `${label}: ${name}` : undefined}
      aria-hidden={label ? undefined : true}
      data-slot="signal-strength"
      data-status={status}
      data-level={lit}
      data-size={size}
      className={cn("inline-flex", className)}
      style={style}
      {...props}
    >
      {[1, 2, 3, 4].map((bar) => (
        <i key={bar} data-on={bar <= lit ? "" : undefined} style={{ "--ss-i": bar } as CSSProperties} />
      ))}
      {status === "offline" && <b data-slot="ss-slash" />}
    </span>
  );
}

/* signal-strength.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Signal strength: bars rise in turn; colour follows quality; a sweep while searching. */
  [data-slot="signal-strength"] { --ss-w: 4px; --ss-h: 16px; position: relative; align-items: flex-end; gap: 2px; height: var(--ss-h); color: var(--muted-foreground); }
  [data-slot="signal-strength"][data-size="sm"] { --ss-w: 3px; --ss-h: 12px; }
  [data-slot="signal-strength"][data-level="1"] { color: var(--destructive); }
  [data-slot="signal-strength"][data-level="2"] { color: var(--warning); }
  [data-slot="signal-strength"]:is([data-level="3"], [data-level="4"]) { color: var(--success); }
  [data-slot="signal-strength"] i { width: var(--ss-w); height: calc(var(--ss-h) * (0.25 + var(--ss-i) * 0.1875)); border-radius: 1px; background: color-mix(in oklab, var(--foreground) 16%, transparent); transform-origin: bottom; transition: background-color var(--duration-normal) var(--ease-out) calc(var(--ss-i) * 40ms), scale var(--duration-normal) var(--ease-settle) calc(var(--ss-i) * 40ms); }
  [data-slot="signal-strength"] i[data-on] { background: currentColor; }
  [data-slot="signal-strength"][data-status="searching"] i { animation: ss-sweep 1.2s var(--ease-in-out) calc(var(--ss-i) * 120ms) infinite; }
  [data-slot="signal-strength"] [data-slot="ss-slash"] { position: absolute; left: -2px; right: -2px; top: 50%; height: 1.5px; background: var(--muted-foreground); rotate: -40deg; box-shadow: 0 0 0 1px var(--background); }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="signal-strength"] i { transition: none; }
    [data-slot="signal-strength"][data-status="searching"] i { animation: ss-pulse 2s ease-in-out infinite; }
  }
  @keyframes ss-sweep { 0%, 100% { background-color: color-mix(in oklab, var(--foreground) 16%, transparent); } 30% { background-color: var(--muted-foreground); } }
  @media (prefers-reduced-motion: reduce) {
    @keyframes ss-pulse { 50% { opacity: 0.5; } }
  }
}
